#include "TrackMetadata.h"

namespace MetadataCleaner
{
namespace
{
    bool isUuidLike (const juce::String& s)
    {
        // 8-4-4-4-12 hex
        auto t = s.trim();
        if (t.length() == 36 && t[8] == '-' && t[13] == '-' && t[18] == '-' && t[23] == '-')
        {
            for (int i = 0; i < t.length(); ++i)
            {
                auto c = t[i];
                if (c == '-') continue;
                if (juce::CharacterFunctions::getHexDigitValue (c) < 0) return false;
            }
            return true;
        }
        return false;
    }

    bool isHexId (const juce::String& s)
    {
        auto t = s.trim().removeCharacters ("- _");
        if (t.length() < 12 || t.length() > 64) return false;
        for (int i = 0; i < t.length(); ++i)
            if (juce::CharacterFunctions::getHexDigitValue (t[i]) < 0)
                return false;
        return true;
    }

    bool containsAiKeyword (const juce::String& lower)
    {
        static const char* keys[] = {
            "suno", "udio", "riffusion", "aiva", "soundraw", "boomy", "mubert",
            "ai generated", "ai-generated", "generated by", "generated with",
            "chatgpt", "openai", "midjourney", "stable audio", "musicgen",
            "prompt:", "negative prompt", "seed:", "cfg scale", "model:",
            "track id", "clip id", "generation id", "job id", "request id",
            "untitled ai", "ai music", "made with ai", "created by ai"
        };
        for (auto* k : keys)
            if (lower.contains (k)) return true;
        return false;
    }

    juce::String stripMasteringExportDecorators (juce::String name)
    {
        auto lower = name.toLowerCase();
        if (lower.startsWith ("landr-"))
            name = name.substring (6);

        for (auto suffix : { juce::String ("-Balanced-Medium"),
                             juce::String ("-Balanced-High"),
                             juce::String ("-Balanced-Low") })
        {
            if (name.endsWithIgnoreCase (suffix))
                name = name.dropLastCharacters (suffix.length());
        }
        return name.trimCharactersAtEnd ("-_ ").trim();
    }
}

bool looksLikeAiJunk (const juce::String& s)
{
    auto t = s.trim();
    if (t.isEmpty()) return true;
    if (isUuidLike (t) || isHexId (t)) return true;
    auto lower = t.toLowerCase();
    if (containsAiKeyword (lower)) return true;
    // Pure numeric IDs
    if (t.length() >= 8 && t.containsOnly ("0123456789")) return true;
    // "Track_ab12cd34" style
    if (lower.startsWith ("track_") || lower.startsWith ("song_") || lower.startsWith ("gen_"))
        return true;
    return false;
}

juce::String cleanField (const juce::String& s)
{
    auto t = s.trim();
    if (t.isEmpty()) return {};

    // Strip bracketed / parenthetical tails first: "My Song [Suno]" → "My Song"
    juce::String out;
    bool inBracket = false;
    for (int i = 0; i < t.length(); ++i)
    {
        auto c = t[i];
        if (c == '[' || c == '(') { inBracket = true; continue; }
        if (c == ']' || c == ')') { inBracket = false; continue; }
        if (! inBracket) out += c;
    }
    out = out.trim();
    // Also strip trailing " - Suno" / " | Udio" style suffixes
    for (auto* suffix : { " - suno", " – suno", " | suno", " - udio", " | udio", " - ai" })
    {
        auto lower = out.toLowerCase();
        if (lower.endsWithIgnoreCase (suffix))
            out = out.dropLastCharacters ((int) std::strlen (suffix)).trim();
    }
    while (out.contains ("  ")) out = out.replace ("  ", " ");
    if (out.isEmpty() || looksLikeAiJunk (out)) return {};
    return out;
}

void guessFromFilename (const juce::File& f, juce::String& outArtist, juce::String& outTitle)
{
    outArtist = {};
    outTitle = {};
    auto base = stripMasteringExportDecorators (f.getFileNameWithoutExtension().trim());
    if (base.isEmpty() || looksLikeAiJunk (base)) return;

    // Artist - Title | Artist – Title | Artist _ Title
    juce::String sep;
    if (base.contains (" - ")) sep = " - ";
    else if (base.contains (" – ")) sep = " – ";
    else if (base.contains (" — ")) sep = " — ";
    else if (base.contains ("_")) // only if single underscore split looks good
    {
        auto parts = juce::StringArray::fromTokens (base, "_", "");
        if (parts.size() == 2)
        {
            outArtist = cleanField (parts[0].replaceCharacter ('-', ' '));
            outTitle = cleanField (parts[1].replaceCharacter ('-', ' '));
            return;
        }
    }

    if (sep.isNotEmpty())
    {
        outArtist = cleanField (base.upToFirstOccurrenceOf (sep, false, false));
        outTitle = cleanField (base.fromFirstOccurrenceOf (sep, false, false));
        return;
    }

    outTitle = cleanField (base.replaceCharacter ('_', ' ').replaceCharacter ('-', ' '));
}

static juce::String pickMeta (const juce::StringPairArray& raw, std::initializer_list<const char*> keys)
{
    for (auto* k : keys)
    {
        // case-insensitive scan
        for (int i = 0; i < raw.size(); ++i)
        {
            if (raw.getAllKeys()[i].equalsIgnoreCase (k))
            {
                auto v = cleanField (raw.getAllValues()[i]);
                if (v.isNotEmpty()) return v;
            }
        }
    }
    return {};
}

TrackMetadata fromFileHints (const juce::StringPairArray& rawMeta, const juce::File& sourceFile)
{
    TrackMetadata m;
    m.title  = pickMeta (rawMeta, { "title", "TITLE", "INAM", "©nam", "TIT2" });
    m.artist = pickMeta (rawMeta, { "artist", "ARTIST", "IART", "©ART", "TPE1", "author" });
    m.album  = pickMeta (rawMeta, { "album", "ALBUM", "IPRD", "©alb", "TALB" });
    m.genre  = pickMeta (rawMeta, { "genre", "GENRE", "IGNR", "©gen", "TCON" });
    m.year   = pickMeta (rawMeta, { "date", "year", "YEAR", "ICRD", "©day", "TYER", "TDRC" });
    // Never keep AI comments/prompts
    auto comment = pickMeta (rawMeta, { "comment", "COMMENT", "ICMT", "©cmt" });
    if (comment.isNotEmpty() && ! looksLikeAiJunk (comment) && ! comment.toLowerCase().contains ("prompt"))
        m.comment = comment;

    juce::String fa, ft;
    guessFromFilename (sourceFile, fa, ft);
    if (m.title.isEmpty()) m.title = ft;
    if (m.artist.isEmpty()) m.artist = fa;

    return m;
}

TrackMetadata applyUserEdits (TrackMetadata base,
                              const juce::String& title,
                              const juce::String& artist,
                              const juce::String& album,
                              const juce::String& genre,
                              const juce::String& year)
{
    auto t = title.trim();
    auto a = artist.trim();
    if (t.isNotEmpty()) base.title = t;
    if (a.isNotEmpty()) base.artist = a;
    if (album.trim().isNotEmpty()) base.album = album.trim();
    if (genre.trim().isNotEmpty()) base.genre = genre.trim();
    if (year.trim().isNotEmpty()) base.year = year.trim();
    // Clear any residual junk after user confirm
    if (looksLikeAiJunk (base.title)) base.title = t;
    if (looksLikeAiJunk (base.artist)) base.artist = a;
    return base;
}

bool needsUserInput (const TrackMetadata& m)
{
    return ! m.hasCoreIdentity();
}
} // namespace MetadataCleaner
